import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { DeploymentRegistryService } from '@services/deployment-registry.service';
import { ToastService } from '@services/toast.service';
import { IconComponent } from '@components/ui/icon/icon.component';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'app-registry-admin',
  standalone: true,
  imports: [CommonModule, FormsModule, IconComponent, TranslateModule],
  templateUrl: './registry-admin.component.html',
  styleUrl: './registry-admin.component.css'
})
export class RegistryAdminComponent implements OnInit {
  // Accepted Tokens State
  newTokenAddress = '';
  newLockId: number | null = null;
  updateTokenAddress = '';
  updateLockId: number | null = null;

  // Whitelist State
  whitelistAddressesInput = '';
  revokeAddressesInput = '';

  // Bytecode State
  bytecodeContractName = '';
  bytecodeContent = '';

  isRegistryAvailable = false;

  constructor(
    private registryService: DeploymentRegistryService,
    private toast: ToastService
  ) {}

  ngOnInit() {
    this.isRegistryAvailable = this.registryService.isAvailable();
  }

  async addAcceptedToken() {
    if (!this.newTokenAddress || !this.newLockId) {
      this.toast.error('Veuillez remplir l\'adresse du Token et le LockID');
      return;
    }
    const success = await this.registryService.addAcceptedTokenWithLockId(this.newTokenAddress.trim(), this.newLockId);
    if (success) {
      this.newTokenAddress = '';
      this.newLockId = null;
    }
  }

  async updateTokenLock() {
    if (!this.updateTokenAddress || !this.updateLockId) {
      this.toast.error('Veuillez remplir l\'adresse du Token et le nouveau LockID');
      return;
    }
    const success = await this.registryService.setTokenLockId(this.updateTokenAddress.trim(), this.updateLockId);
    if (success) {
      this.updateTokenAddress = '';
      this.updateLockId = null;
    }
  }

  async processWhitelist(action: 'grant' | 'revoke') {
    const input = action === 'grant' ? this.whitelistAddressesInput : this.revokeAddressesInput;
    if (!input) return;

    // Split by comma or newline and clean up
    const addresses = input.split(/[\n,]+/).map(a => a.trim()).filter(a => a !== '');
    if (addresses.length === 0) {
      this.toast.error('Aucune adresse valide fournie');
      return;
    }

    let success = false;
    if (action === 'grant') {
      success = await this.registryService.grantDeployments(addresses);
      if (success) this.whitelistAddressesInput = '';
    } else {
      success = await this.registryService.revokeDeployments(addresses);
      if (success) this.revokeAddressesInput = '';
    }
  }

  async storeBytecode() {
    if (!this.bytecodeContractName || !this.bytecodeContent) {
      this.toast.error('Nom de contrat ou bytecode manquant');
      return;
    }
    const success = await this.registryService.storeBytecode(this.bytecodeContractName.trim(), this.bytecodeContent.trim());
    if (success) {
      this.bytecodeContractName = '';
      this.bytecodeContent = '';
    }
  }
}
